/**
 * The iOS device registry: which devices exist, which tokens they present, and
 * which are currently connected.
 *
 * Storage lives in the agent directory (`ios.db`), next to the Android registry
 * and for the same reason: the project work directory is mounted into the
 * container, and a device list must survive it.
 *
 * A deviceId is generated by SentinelBridge on first start and kept in the
 * device's Keychain; the token is created by the operator in the console. The
 * two are separate on purpose — reinstalling the App must not re-register the
 * device, and deleting a token must make the secret unusable immediately.
 *
 * The schema stays separate from `droids.db` on purpose: the Android table is
 * shaped around `sdkInt`/`rooted`, this one around the jailbreak form and the
 * architecture, and forcing both into one table would leave half the columns
 * permanently null on each side.
 */

import { randomUUID } from "node:crypto";
import { join } from "node:path";
import type { IosHelloFrame, IosJailbreakForm } from "./ios-protocol.ts";
import type { SqliteDatabase } from "./sqlite.ts";
import { openSqliteDatabase } from "./sqlite.ts";

export function iosDbPath(agentDir: string): string {
	return join(agentDir, "ios.db");
}

export interface IosDevice {
	id: string;
	/** Operator-editable label; defaults to the model the device reported. */
	name: string;
	model: string;
	osVersion: string;
	build: string;
	/** arm64 / arm64e. */
	arch: string;
	jailbreakForm: IosJailbreakForm;
	jailbreakName: string;
	jailbreakVersion: string;
	hasRoot: boolean;
	online: boolean;
	tokenId: string;
	firstSeen: string;
	lastSeen: string;
	/**
	 * Runtime-only, never persisted: the socket is open but the device stopped
	 * sending anything. A suspended App looks exactly like this — the kernel can
	 * keep the connection ESTABLISHED while no thread runs.
	 */
	stale?: boolean;
	/** Runtime-only: milliseconds since the device's last frame (0 when fresh). */
	idleMs?: number;
}

export interface IosToken {
	id: string;
	label: string;
	token: string;
	createdAt: string;
	lastUsedAt: string | null;
}

export interface IosDeviceFacts {
	deviceId: string;
	model: string;
	osVersion: string;
	build: string;
	arch: string;
	jailbreakForm: IosJailbreakForm;
	jailbreakName: string;
	jailbreakVersion: string;
	hasRoot: boolean;
}

const SCHEMA = `
CREATE TABLE IF NOT EXISTS ios_tokens (
  id TEXT PRIMARY KEY,
  label TEXT NOT NULL,
  token TEXT NOT NULL,
  created_at TEXT NOT NULL,
  last_used_at TEXT
);
CREATE TABLE IF NOT EXISTS ios_devices (
  id TEXT PRIMARY KEY,
  name TEXT NOT NULL,
  model TEXT NOT NULL,
  os_version TEXT NOT NULL,
  build TEXT NOT NULL,
  arch TEXT NOT NULL,
  jailbreak_form TEXT NOT NULL,
  jailbreak_name TEXT NOT NULL,
  jailbreak_version TEXT NOT NULL,
  has_root INTEGER NOT NULL,
  online INTEGER NOT NULL DEFAULT 0,
  token_id TEXT NOT NULL,
  first_seen TEXT NOT NULL,
  last_seen TEXT NOT NULL
);
CREATE INDEX IF NOT EXISTS idx_ios_devices_online ON ios_devices(online, last_seen);
CREATE TABLE IF NOT EXISTS ios_meta (
  key TEXT PRIMARY KEY,
  value TEXT NOT NULL
);
DROP TABLE IF EXISTS ios_pairings;
`;

interface DeviceRow {
	id: string;
	name: string;
	model: string;
	os_version: string;
	build: string;
	arch: string;
	jailbreak_form: string;
	jailbreak_name: string;
	jailbreak_version: string;
	has_root: number;
	online: number;
	token_id: string;
	first_seen: string;
	last_seen: string;
}

interface TokenRow {
	id: string;
	label: string;
	token: string;
	created_at: string;
	last_used_at: string | null;
}

const JAILBREAK_FORMS: readonly IosJailbreakForm[] = ["rootful", "rootless", "roothide", "unknown"];

/** Coerce whatever a device sent into a form the console understands. */
export function normalizeJailbreakForm(value: unknown): IosJailbreakForm {
	return typeof value === "string" && (JAILBREAK_FORMS as readonly string[]).includes(value)
		? (value as IosJailbreakForm)
		: "unknown";
}

function now(): string {
	return new Date().toISOString();
}

function toDevice(row: DeviceRow): IosDevice {
	return {
		id: row.id,
		name: row.name,
		model: row.model,
		osVersion: row.os_version,
		build: row.build,
		arch: row.arch,
		jailbreakForm: normalizeJailbreakForm(row.jailbreak_form),
		jailbreakName: row.jailbreak_name,
		jailbreakVersion: row.jailbreak_version,
		hasRoot: row.has_root === 1,
		online: row.online === 1,
		tokenId: row.token_id,
		firstSeen: row.first_seen,
		lastSeen: row.last_seen,
	};
}

function toToken(row: TokenRow): IosToken {
	return {
		id: row.id,
		label: row.label,
		token: row.token,
		createdAt: row.created_at,
		lastUsedAt: row.last_used_at,
	};
}

export class IosStore {
	private readonly db: SqliteDatabase;

	constructor(path: string) {
		this.db = openSqliteDatabase(path);
		this.db.exec(SCHEMA);
	}

	// -- tokens ---------------------------------------------------------------

	createToken(label: string): IosToken {
		const token: IosToken = {
			id: randomUUID(),
			label: label.trim() || "未命名设备",
			// Long enough that guessing is hopeless, short enough to type into the App once.
			token: `ios_${randomUUID().replace(/-/g, "")}`,
			createdAt: now(),
			lastUsedAt: null,
		};
		this.db
			.prepare("INSERT INTO ios_tokens (id, label, token, created_at, last_used_at) VALUES (?, ?, ?, ?, NULL)")
			.run(token.id, token.label, token.token, token.createdAt);
		return token;
	}

	listTokens(): IosToken[] {
		const rows = this.db.prepare("SELECT * FROM ios_tokens ORDER BY created_at DESC, id").all() as TokenRow[];
		return rows.map(toToken);
	}

	/** The token record for a presented secret, or undefined (unknown or deleted). */
	findToken(token: string): IosToken | undefined {
		if (!token) return undefined;
		const row = this.db.prepare("SELECT * FROM ios_tokens WHERE token = ?").get(token) as TokenRow | undefined;
		return row ? toToken(row) : undefined;
	}

	touchToken(id: string): void {
		this.db.prepare("UPDATE ios_tokens SET last_used_at = ? WHERE id = ?").run(now(), id);
	}

	/** Delete a token: the secret can never authenticate again. */
	deleteToken(id: string): boolean {
		const result = this.db.prepare("DELETE FROM ios_tokens WHERE id = ?").run(id);
		return Number(result.changes ?? 0) > 0;
	}

	// -- devices --------------------------------------------------------------

	/**
	 * Register (or refresh) a device that just said hello. The operator's label
	 * survives: only the reported facts and the timestamps are refreshed.
	 */
	upsertDevice(hello: IosHelloFrame, tokenId: string): IosDevice {
		const at = now();
		const facts: IosDeviceFacts = {
			deviceId: hello.deviceId,
			model: String(hello.model || "未知机型"),
			osVersion: String(hello.osVersion || "未知"),
			build: String(hello.build ?? ""),
			arch: String(hello.arch || "unknown"),
			jailbreakForm: normalizeJailbreakForm(hello.jailbreak?.form),
			jailbreakName: String(hello.jailbreak?.name ?? ""),
			jailbreakVersion: String(hello.jailbreak?.version ?? ""),
			hasRoot: hello.hasRoot === true,
		};
		const existing = this.db.prepare("SELECT * FROM ios_devices WHERE id = ?").get(facts.deviceId) as
			| DeviceRow
			| undefined;
		if (existing) {
			this.db
				.prepare(
					"UPDATE ios_devices SET model = ?, os_version = ?, build = ?, arch = ?, jailbreak_form = ?, jailbreak_name = ?, jailbreak_version = ?, has_root = ?, online = 1, token_id = ?, last_seen = ? WHERE id = ?",
				)
				.run(
					facts.model,
					facts.osVersion,
					facts.build,
					facts.arch,
					facts.jailbreakForm,
					facts.jailbreakName,
					facts.jailbreakVersion,
					facts.hasRoot ? 1 : 0,
					tokenId,
					at,
					facts.deviceId,
				);
		} else {
			this.db
				.prepare(
					"INSERT INTO ios_devices (id, name, model, os_version, build, arch, jailbreak_form, jailbreak_name, jailbreak_version, has_root, online, token_id, first_seen, last_seen) VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 1, ?, ?, ?)",
				)
				.run(
					facts.deviceId,
					facts.model,
					facts.model,
					facts.osVersion,
					facts.build,
					facts.arch,
					facts.jailbreakForm,
					facts.jailbreakName,
					facts.jailbreakVersion,
					facts.hasRoot ? 1 : 0,
					tokenId,
					at,
					at,
				);
		}
		this.touchToken(tokenId);
		return this.getDevice(facts.deviceId) as IosDevice;
	}

	getDevice(id: string): IosDevice | undefined {
		const row = this.db.prepare("SELECT * FROM ios_devices WHERE id = ?").get(id) as DeviceRow | undefined;
		return row ? toDevice(row) : undefined;
	}

	listDevices(): IosDevice[] {
		const rows = this.db
			.prepare("SELECT * FROM ios_devices ORDER BY online DESC, last_seen DESC, id")
			.all() as DeviceRow[];
		return rows.map(toDevice);
	}

	onlineDevices(): IosDevice[] {
		const rows = this.db
			.prepare("SELECT * FROM ios_devices WHERE online = 1 ORDER BY last_seen DESC, id")
			.all() as DeviceRow[];
		return rows.map(toDevice);
	}

	setDeviceOnline(id: string, online: boolean): void {
		this.db.prepare("UPDATE ios_devices SET online = ?, last_seen = ? WHERE id = ?").run(online ? 1 : 0, now(), id);
	}

	renameDevice(id: string, name: string): boolean {
		const trimmed = name.trim();
		if (!trimmed) return false;
		const result = this.db.prepare("UPDATE ios_devices SET name = ? WHERE id = ?").run(trimmed, id);
		return Number(result.changes ?? 0) > 0;
	}

	removeDevice(id: string): boolean {
		const result = this.db.prepare("DELETE FROM ios_devices WHERE id = ?").run(id);
		return Number(result.changes ?? 0) > 0;
	}

	getMeta(key: string): string | undefined {
		const row = this.db.prepare("SELECT value FROM ios_meta WHERE key = ?").get(key) as { value: string } | undefined;
		return row?.value;
	}

	setMeta(key: string, value: string): void {
		this.db
			.prepare(
				"INSERT INTO ios_meta (key, value) VALUES (?, ?) ON CONFLICT(key) DO UPDATE SET value = excluded.value",
			)
			.run(key, value);
	}

	close(): void {
		this.db.close();
	}
}
